var b="url",c="planning_board_-_daily.html",d="generationDate",e=new Date(1792384273103.47),f="defaultAdaptiveView",g="name",h="",i="size",j="width",k=428,l="height",m=926,n="adaptiveViews",o="sketchKeys",p="s0",q="variables",r="OnLoadVariable",s="v",t="a",u="nz",v="tash1",w="dymali",x="dykhaz",y="mopay",z="mopayt",A="nz2",B="currentTime",C="SourceForm",D="lg",E="vi",F="check",G="san",H="ba",I="loginv",J="inpa",K="NewVariable",L="page",M="packageId",N="e01b3f8fc1434a0897ad663792f01cb9",O="type",P="Axure:Page",Q="Planning Board - Daily",R="notes",S="annotations",T="fn",U="1",V="ownerId",W="74931dd0b69b48b397efe97ade81e704",X="label",Y="نیروهای استفاده نشده",Z="Note",ba="<p><span>پرسنلی که در این روز در هیچ انباری به عضویت هیچ تیمی در نیامده اند در این لیست نمایش داده میشود.</span></p>",bb="2",bc="ce445345b8d047b2b9df7be89675ed85",bd="(Dynamic Panel)",be="<p><span>جهت ایجاد تیم جدید از دکمه ایجاد تیم جدید استفاده میشود. </span></p><p><span><br></span></p><p><span>----------------------------------</span></p><p><span>عنوان تیم ها با شمارنده و به ترتیب ایجاد خواهد شد.</span></p><p><span><br></span></p><p><span>-----------------------------------</span></p><p><span>با حذف تیم، شمارنده ها مجدد از 1 چیدمان میشوند</span></p><p><span><br></span></p><p><span>-----------------------------------</span></p><p><span>حذف تیم در صورتی امکان پذیر است که آن تیم به هیچ پک بارگیری در آن روز اختصاص داده نشده باشد</span></p><p><span>در صورت عدم رعایت این شرط پیغام خطا بدهد</span></p><p><span>&quot; این تیم در پک بارگیری .. تخصیص شده است و قابل حذف نمی باشد&quot;</span></p><p><span>-------------------------------------</span></p><p><span>با زدن دکمه افزودن عضو جدید یک ردیف جهت اضافه کردن عضو جدید ایجاد میگردد</span></p><p><span>--------------------------------</span></p><p><span><br></span></p><p><span>به هنگام انتخاب نام عضو ، لیست کلیه پرسنل انبارها به سرپرست نمایش داده میشود. </span></p><p><span>به عبارتی تمامی سرپرستان در تمامی انبارها لیست کلیه پرسنل را مشاهده و برای هرروز نفرات هر تیم در انبار خود انتخاب می نمایند.</span></p><p><span><br></span></p><p><span>-------------------------------------</span></p><p><span>در هنگام ثبت و یا ذخیره پیش نویس</span></p><p><span>شرط زیر چک شود:</span></p><p><span><br></span></p><p><span>هر پرسنل در بازه زمانی انتخاب شده، در هیچ انبار و تیم دیگری توسط سرپرست انبارها انتخاب نشده باشد. یعنی هر پرسنل انبار در هر روز و در هر زمان تنها میتوانددر یک تیم از یک انبار عضو باشد.</span></p><p><span>ولی اگر زمان ها با یکدیگر تداخل نداشته باشند انتخاب در بیش از یک تیم و یک انبار مانعی ندارد.</span></p><p><span>در صورت رعایت نبودن این شرط پیغام خطا بدهد. </span></p><p><span>نام و نام خانوادگی در این بازه زمانی در انبار ...... دارای تیم می باشد.</span></p><p><span>---------------------------------------</span></p><p><span>حذف عضو از تیم در صورتی امکان پذیر است که آن تیم به هیچ پک بارگیری در آن روز اختصاص داده نشده باشد</span></p><p><span>در صورت عدم رعایت این شرط پیغام خطا بدهد</span></p><p><span>&quot; این تیم در پک بارگیری .. تخصیص شده است و قابل حذف نمی باشد</span></p><p><span>---------------------------------------</span></p><p><span>&nbsp;هر تیم در هر زمان تنها یک مسئول بارگیری میتواند داشته باشد یعنی بر مبنای ساعت کنترل شود. به عنوان مثال از ساعت 6 تا 12 یک مسئول بارگیری و از ساعت 12 تا 16:30 یک مسئول بارگیری دیگر. داشته باشد مانعی ندارد. ولی نمیتواند در یک بازه زمانی دو مسئول بارگیری متفاوت داشته باشد</span></p><p><span>برای دو سمت دیگر هر تیم در هر زمان میتواند بیش از یکی داشته باشد.</span></p>",bf="style",bg="baseStyle",bh="627587b6038d43cca051c114ac41ad32",bi="pageAlignment",bj="center",bk="fill",bl="fillType",bm="solid",bn="color",bo=0xFFFFFFFF,bp="image",bq="imageAlignment",br="near",bs="imageRepeat",bt="auto",bu="favicon",bv="sketchFactor",bw="0",bx="colorStyle",by="appliedColor",bz="fontName",bA="Applied Font",bB="borderWidth",bC="borderVisibility",bD="borderFill",bE=0xFF797979,bF="cornerRadius",bG="cornerVisibility",bH="outerShadow",bI="on",bJ=false,bK="offsetX",bL=5,bM="offsetY",bN="blurRadius",bO="spread",b